// Safely fetch config from 'Edit Fields' node or use defaults
let varianceThreshold = 0.05;
try {
  varianceThreshold = $('Edit Fields').first().json.variance_threshold || 0.05;
} catch (e) {
  varianceThreshold = 0.05;
}

// All incoming items loop
for (const item of $input.all()) {
  const webSku = item.json.sku || item.json.web_sku || item.json.product_id || "N/A";
  const scrapedPrice = parseFloat(item.json.scraped_price || item.json.price || 0);
  const baselinePrice = parseFloat(item.json.baseline_price || item.json.expected_price || 0);

  let priceDiff = scrapedPrice - baselinePrice;
  let variancePercent = 0;
  if (baselinePrice > 0) {
    variancePercent = (priceDiff / baselinePrice) * 100;
  }

  let status = "Matched";
  if (baselinePrice === 0) {
    status = "Not Found on Master List";
  } else if (Math.abs(variancePercent) > (varianceThreshold * 100)) {
    status = `Price Variance (${variancePercent.toFixed(2)}%)`;
  }

  item.json.audit_sku = webSku;
  item.json.audit_scraped_price = scrapedPrice;
  item.json.audit_baseline_price = baselinePrice;
  item.json.audit_variance = priceDiff;
  item.json.audit_status = status;
}

return $input.all();
